import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.CZTQpGgQ.js";const i=JSON.parse('{"title":"机器人“组团”下田 芦笋采收分拣一条龙作业","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"机器人“组团”下田 芦笋采收分拣一条龙作业","date":"2026-11-28T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202611/t20261126_6489770.htm","summary":"芦笋田垄间,机器人往来穿梭,采收、转运、分拣环环相扣。日前,由农业农村部南京农业机械化研究所农业机器人创新团队研制的芦笋智能采收机器人、多足转运机器人、芦笋智能分拣机器人集中亮相,田间流水作业,展现了农业机器人技术与果蔬产业需求深度融合的阶段性成果。\\n芦笋采收机器人及作业现场\\n多足转运机器人\\n芦笋分拣机器人\\n...\\n","contentHash":"3ce09ebb22f738eaf67c6a422d5e651e","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-11-28-机器人-组团-下田-芦笋采收分拣一条龙作业.md","filePath":"news/2026-11-28-机器人-组团-下田-芦笋采收分拣一条龙作业.md"}'),n={name:"news/2026-11-28-机器人-组团-下田-芦笋采收分拣一条龙作业.md"};function s(o,e,p,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="机器人-组团-下田-芦笋采收分拣一条龙作业" tabindex="-1">机器人“组团”下田 芦笋采收分拣一条龙作业 <a class="header-anchor" href="#机器人-组团-下田-芦笋采收分拣一条龙作业" aria-label="Permalink to &quot;机器人“组团”下田 芦笋采收分拣一条龙作业&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202611/t20261126_6489770.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-11-28 摘要: 芦笋田垄间,机器人往来穿梭,采收、转运、分拣环环相扣。日前,由农业农村部南京农业机械化研究所农业机器人创新团队研制的芦笋智能采收机器人、多足转运机器人、芦笋智能分拣机器人集中亮相,田间流水作业,展现了农业机器人技术与果蔬产业需求深度融合的阶段性成果。 芦笋采收机器人及作业现场 多足转运机器人 芦笋分拣机器人 ...</p></blockquote><p>芦笋采收机器人及作业现场</p><p>多足转运机器人</p><p>芦笋分拣机器人</p><p>长期以来,芦笋等特色果蔬种植饱受人工短缺、用工成本高、劳动强度大、作业标准不统一等痛点困扰。尤其是丘陵山地、设施大棚等复杂作业场景,传统农机适配性差、灵活性不足,严重制约着果蔬产业的现代化升级。</p><p>科研团队联合各方力量开展跨领域协同创新,以芦笋为切入点开展关键技术攻关。芦笋智能采收机器人可自主完成嫩茎识别、采摘点精准定位、夹持剪切和自动收集,嫩茎识别准确率超过95%,采摘点定位误差控制在5毫米以内,“慧眼”识笋、“巧手”下刀;多足转运机器人可地形自适应、自主跟随,有效载荷达100千克,田间农资和农产品转运轻松自如;芦笋智能分拣机器人集视觉检测、自动切根、多维分级于一体,上料-检测-切割-分拣-收集一气呵成,检测精度毫米级,分选准确率超过95%。</p><p>三款智能装备协同联动,可实现芦笋从田间采收、田间转运到产后分拣的全链条智能化作业,完成了果蔬农机从单一环节自动化向全流程智能协同作业的跨越式升级。未来,随着农业机器人不断“上岗”,特色果蔬生产有望更省力、更精准、更高效。(光明网记者宋雅娟)</p><p>来源: 光明网</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202611/t20261126_6489770.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',10)])])}const h=t(n,[["render",s]]);export{i as __pageData,h as default};
